    public static void main(String[] args) {
        int[] harga = {45000, 120000, 15000, 87000};
        for (int i = 0; i < harga.length - 1; i++) {
            int m = i;
            for (int j = i + 1; j < harga.length; j++) {
                if (harga[j] > harga[m]) m = j;     // cari yang TERBESAR
            }
            int tmp = harga[i]; harga[i] = harga[m]; harga[m] = tmp;
        }
        System.out.println("Dari termahal: " + Arrays.toString(harga));
    }
}

public class Main {
    public static void main(String[] args) {
        int[] ukuran = {10, 100, 1000};
        for (int n : ukuran) {
            int langkah = 0;
            for (int i = 0; i < n; i++) {
                langkah++;
            }
            System.out.println("n = " + n + " -> " + langkah + " langkah");
        }
    }
}

public class Main {
