public class Main {
    public static void main(String[] args) {
        int[] ukuran = {16, 1024, 1048576};
        for (int n : ukuran) {
            int langkah = 0;
            for (int i = n; i > 1; i /= 2) {
                langkah++;
            }
            System.out.println("n = " + n + " -> " + langkah + " langkah");
        }
    }
}

